    ".contact-section__feature:nth-child(1) .contact-section__feature-title": { en: "Humanized Service", es: "Atención Humanizada" },
    ".contact-section__feature:nth-child(1) .contact-section__feature-text": { en: "A dedicated team to understand your needs with closeness and clarity.", es: "Equipo dedicado para entender su necesidad con cercanía y claridad." },
    ".contact-section__feature:nth-child(2) .contact-section__feature-title": { en: "Quick Response", es: "Respuesta Rápida" },
