    ".svx-context:nth-child(2) h3": { en: "Companies, institutions and NGOs", es: "Empresas, instituciones y ONG" },
    ".svx-context:nth-child(2) p": { en: "Capacity-building initiatives for NGOs and social movements, alongside companies and institutions.", es: "Acciones de fortalecimiento institucional de ONG y movimientos sociales, junto a empresas e instituciones." },
    ".svx-context:nth-child(3) h3": { en: "International projects and missions", es: "Proyectos internacionales y misiones" },
    ".svx-context:nth-child(3) p": { en: "Precise communication in diplomatic meetings and technical missions.", es: "Comunicación precisa en encuentros diplomáticos y misiones técnicas." },
    ".svx-context:nth-child(4) h3": { en: "Specialized content and documents", es: "Contenidos y documentos especializados" },
