    ".svx-group:nth-of-type(1) .svx-card:nth-of-type(2) p": { en: "Ideal for corporate meetings, international conferences, training and hybrid events: RSI turns any videoconferencing platform into a truly global space.", es: "Ideal para reuniones corporativas, conferencias internacionales, capacitaciones y eventos híbridos: la ISR transforma cualquier plataforma de videoconferencia en un espacio verdaderamente global." },
    ".svx-group:nth-of-type(2) .svx-group__kind": { en: "Core service", es: "Servicio principal" },
    ".svx-group:nth-of-type(2) h2": { en: "Translation", es: "Traducción" },
